    TContext = unknown>(options?: { mutation?:UseMutationOptions<Awaited<ReturnType<typeof approveMigration>>, TError,ApproveMigrationMutationVariables, TContext>, }
): UseMutationOptions<Awaited<ReturnType<typeof approveMigration>>, TError,ApproveMigrationMutationVariables, TContext> => {

const mutationKey = getApproveMigrationMutationKey();
const {mutation: mutationOptions} = options ?
      options.mutation && 'mutationKey' in options.mutation && options.mutation.mutationKey ?
      options
      : {...options, mutation: {...options.mutation, mutationKey}}
      : {mutation: { mutationKey, }};




      const mutationFn: MutationFunction<Awaited<ReturnType<typeof approveMigration>>, ApproveMigrationMutationVariables> = (props) => {
          const {id} = props ?? {};

          return  approveMigration(id,)
        }






  return  { mutationFn, ...mutationOptions }}

    export type ApproveMigrationMutationResult = NonNullable<Awaited<ReturnType<typeof approveMigration>>>

    export type ApproveMigrationMutationError = ErrorType<unknown>
    export type ApproveMigrationMutationVariables = {id: string}

    /**
 * @summary Approve completed migration
 */
export const useApproveMigration = <TError = ErrorType<unknown>,
    TContext = unknown>(options?: { mutation?:UseMutationOptions<Awaited<ReturnType<typeof approveMigration>>, TError,ApproveMigrationMutationVariables, TContext>, }
 ): UseMutationResult<
        Awaited<ReturnType<typeof approveMigration>>,
        TError,
        ApproveMigrationMutationVariables,
        TContext
      > => {
      return useMutation(getApproveMigrationMutationOptions(options));
    }

export const getRejectMigrationUrl = (id: string,) => {




  return `/api/migrations/${id}/reject`
}

/**
 * @summary Reject a completed migration
 */
export const rejectMigration = async (id: string, options?: RequestInit): Promise<Migration> => {

  return customFetch<Migration>(getRejectMigrationUrl(id),
  {
    ...options,
    method: 'POST'


  }
);}





